# Executed by build-content-pages.py, with its rendering helpers in scope.
articles=[
('bolgeye-gore-musteri-arastirmasi','Bölgeye göre müşteri araştırması nasıl yapılır?','Bir sektör ve bölge seçerek işletme araştırmasını daraltın. Çıktıyı kontrol edin, önceliklendirin ve görüşme listenizi hazırlayın.',[
('Önce kimi aradığınızı tanımlayın.','Araştırmaya bir işletme türüyle başlayın. “İstanbul’daki işletmeler” geniş bir çerçevedir; “Şişli’deki diş klinikleri” ise neyi değerlendireceğinizi daha açık hale getirir. Sunduğunuz hizmetin hangi işletme için anlamlı olduğunu yazın.','Arama sonucunda görünmek, o işletmenin teklifinize ihtiyaç duyduğu anlamına gelmez. Sektörü seçmek yalnızca araştırmanın kapsamını belirler.'),
('Çalışabileceğiniz bölgeyi seçin.','Sahada görüşme yapıyorsanız ulaşabildiğiniz ilçelerden başlayın. Uzaktan hizmet sunuyorsanız bile ilk çalışmayı birkaç bölgeyle sınırlamak, aynı ölçütlerle kayıtları incelemenizi kolaylaştırır.','Bölgeyi seçerken araştırmanın amacını not edin. Yerel iş birliği, yeni satış görüşmesi ve tedarik araştırması aynı listeyi farklı biçimlerde değerlendirir.'),
('Küçük bir örneği kontrol edin.','Listenin ilk birkaç kaydında işletme adı, türü ve adresi inceleyin. Sonuçlar hedeflediğiniz işletme grubuna uyuyor mu? Şube, benzer isim veya farklı hizmet türü gibi ayrıntıları kontrol edin.','Kaynak profillerde eksik alanlar bulunabilir. Telefon veya web sitesi eksikse bunları uydurarak tamamlamak yerine eksik olarak işaretleyin ve gerekiyorsa ilgili işletmenin resmî kanallarından doğrulayın.'),
('Listenizi çalışma dosyasına dönüştürün.','CSV çıktısını açtıktan sonra araştırma notu, sorumlu kişi ve sonraki adım için ayrı sütunlar ekleyin. Kaynak bilgisini özgün sütunlarda tutmak, sonradan eklenen yorumlarla veriyi karıştırmamanıza yardımcı olur.','Kayıt sayısı yerine uygunluğu önceliklendirin. Her işletme için kısa bir araştırma, daha anlamlı bir görüşme hazırlığı sağlar.'),
('İletişimden önce son kontrolü yapın.','İşletmenin güncel adı, hizmeti ve iletişim kanallarını doğrulayın. Nasıl iletişim kuracağınızı belirlerken veri koruma ve ticari iletişim kurallarını ayrıca değerlendirin.','Veri Burada araştırma ve listeleme aşamasına yardımcı olur. Bir kaydın listede bulunması, mesaj gönderme izni veya satış sonucu garantisi değildir.')]),
('ajanslar-icin-isletme-arastirmasi','Ajanslar için teklif öncesi işletme araştırması','İşletmelerin web ve iletişim bilgilerini karşılaştırarak ajans teklifinizi somut gözlemlere dayandırın. Araştırmadan görüşmeye adım adım ilerleyin.',[
('Bir hizmet, bir sektör seçin.','Web tasarımı, içerik veya reklam hizmetini aynı anda herkese anlatmaya çalışmak yerine tek bir sektörle başlayın. Restoranların menü ve rezervasyon ihtiyacıyla bir mimarlık ofisinin proje sunumu aynı değildir.','İlk araştırmanın amacı satış sonucunu tahmin etmek değil, inceleyeceğiniz işletmeleri tutarlı bir grupta toplamaktır.'),
('Alan adının arkasındaki siteyi inceleyin.','Listede bir web adresi görmeniz, işletmenin sitesinin aktif, güncel veya yetersiz olduğunu kanıtlamaz. Siteyi açın; mobilde okunabilirlik, iletişim yolları ve sunulan hizmetin anlaşılabilirliğini kontrol edin.','Veri Burada web adresini bir bilgi alanı olarak sunar. Ekrandaki örnek site tasarımları, otomatik bir SEO veya performans denetimi yapıldığı anlamına gelmez.'),
('Gözlemi yorumdan ayırın.','“İletişim sayfasında form bulamadım” bir gözlemdir. “Bu işletme müşteri kaybediyor” ise ayrıca kanıt gerektiren bir yorumdur. Çalışma listenizde bu ikisini farklı sütunlarda tutun.','Görüşmeye taşımak istediğiniz her öneri için somut bir ekran veya sayfa notu hazırlayın. İşletmenin neye ihtiyaç duyduğunu ilk görüşmede kendisinden öğrenin.'),
('Teklifinizi işletmeye göre yazın.','Aynı mesajı bütün listeye göndermek yerine sunduğunuz hizmetin bu işletmedeki olası kullanımını düşünün. Restoran için güncellenebilir menü, ofis için okunabilir proje sayfaları gibi somut bir başlangıç belirleyin.','Önerinizi kesin gelir veya sıralama vaadine bağlamayın. Kapsam, teslimat ve başarı ölçütlerini gerçek görüşmede birlikte belirleyin.'),
('Araştırmayı düzenli tutun.','CSV dosyanıza inceleme tarihi, site notu ve sonraki adım sütunları ekleyin. Birden fazla kişi çalışıyorsa kimin hangi işletmeyi araştırdığını işaretleyin.','İletişime geçmeden önce işletme bilgilerini ve kullanacağınız iletişim kanalına ilişkin yükümlülükleri kontrol edin.')]),
('isletme-listesini-excelde-duzenleme','İşletme listesini Excel ve Google Sheets’te düzenleme','CSV işletme listesini UTF-8 ile açın, sütunları ayırın ve araştırma notlarınızı ekleyin. Telefonları metin olarak koruyarak çalışma listenizi hazırlayın.',[
('CSV dosyasını içe aktarın.','Excel’de Veri menüsündeki metin veya CSV içe aktarma seçeneğini kullanın. Dosya kodlamasını UTF-8 olarak seçin. Örnek dosyamızdaki ayırıcı noktalı virgüldür; başka bir dosya için önizlemedeki sütunlara bakarak karar verin.','Türkçe karakterler bozuk görünüyorsa dosyayı tekrar doğru kodlamayla içe aktarın. Aynı dosyayı art arda farklı biçimlerde kaydetmek karakterleri düzeltmeyebilir.'),
('Telefon sütununu metin olarak tutun.','Telefon numaraları hesaplama yapılacak sayılar değildir. Başındaki sıfırların veya + işaretinin değişmemesi için telefon sütununu metin olarak içe aktarın.','Google Sheets’te Dosya → İçe aktar yoluyla CSV’yi açabilirsiniz. İçe aktarma önizlemesinde ayırıcı ve otomatik sayı dönüşümü ayarlarını kontrol edin.'),
('Kaynak sütunlarını koruyun.','İşletme adı, adres, telefon ve web sitesi sütunlarını araştırmadan gelen haliyle saklayın. Kendi yorumlarınızı ayrı sütunlara ekleyin. Böylece gözlem ile kaynak veriyi birbirinden ayırabilirsiniz.','Özgün dosyanın bir kopyasını tutmak, sonraki düzenlemeleri karşılaştırmanızı kolaylaştırır. Dosya adında bölge, sektör ve araştırma tarihini kullanabilirsiniz.'),
('Mükerrer kayıtları dikkatle inceleyin.','Benzer isimler aynı işletme anlamına gelmeyebilir. Adres, şube ve web adresini birlikte karşılaştırın. Yalnızca ada göre bütün benzer kayıtları silmeyin.','Boş bir alanı tahmini bilgiyle doldurmak yerine eksik olarak işaretleyin. Sonradan doğruladığınız bilgi için kontrol tarihi ve kaynağı ekleyin.'),
('İş akışınıza uygun sütunlar ekleyin.','Sorumlu kişi, araştırma notu, durum ve sonraki adım sütunları çoğu ekip için iyi bir başlangıçtır. Bütün satırlarda aynı durum adlarını kullanmak filtrelemeyi kolaylaştırır.','Örnek sayfamızdaki indirilebilir dosya gerçek iletişim bilgisi içermez. Bu dosyayla içe aktarma işlemini ve sütun düzeninizi risksiz biçimde deneyebilirsiniz.')])]
for slug,title,desc,sections in articles:
 toc='<nav class="article-toc" aria-label="Bu rehberde"><b>Bu rehberde</b>'+''.join(f'<a href="#adim-{i+1}">{t}</a>' for i,(t,*_) in enumerate(sections))+'</nav>'
